      "reason": "The text mentions a lack of pooled estimates but does not explicitly confirm the absence of prior systematic reviews, which is required to mark this conditional element as NOT_APPLICABLE."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": null,
      "reason": "This is a diagnostic accuracy review evaluating scoring systems, not a review of intervention effects, so the mechanism of action element does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": null,
      "reason": "This is a diagnostic accuracy review, not a review of complex interventions or delivery contexts, so a logic model is not required."
    }
